def find_minimal_edit(s_in, s_out):
    """Find the minimal edit needed to transform s_in to s_out"""
    # Find first position where they differ
    pos = -1
    for i in range(min(len(s_in), len(s_out))):
        if s_in[i] != s_out[i]:
            pos = i
            break

    if pos == -1:
        # Strings are identical up to min length
        if len(s_in) < len(s_out):
            return ("", s_out[len(s_in):], len(s_in))
        elif len(s_in) > len(s_out):
            return (s_in[len(s_out):], "", len(s_out))
        else:
            return ("", "", -1)  # No difference

    # Find the longest matching prefix
    prefix_len = pos
    # Find the longest suffix match
    suffix_len = 0
    min_len = min(len(s_in) - pos, len(s_out) - pos)

    for i in range(min_len, 0, -1):
        if s_in[pos:pos+i] == s_out[pos:pos+i]:
            suffix_len = i
            break

    if suffix_len == 0:
        # Single character replacement
        return (s_in[pos], s_out[pos], pos)
    else:
        # Substring replacement
        old_sub = s_in[pos:pos+suffix_len]
        new_sub = s_out[pos:pos+suffix_len]
        return (old_sub, new_sub, pos)

inputs = ['whb', 'vez', 'kju', 'jhkb', 'dybw']
outputs = ['gehb', 'vez', 'kjjhu', 'jhkb', 'dgebge']

